CREATE TABLE IF NOT EXISTS candidacy_imports (id TEXT PRIMARY KEY, election_id INTEGER NOT NULL REFERENCES elections(id), chamber TEXT NOT NULL CHECK(chamber='congreso'), version TEXT NOT NULL, source_name TEXT NOT NULL, source_url TEXT, source_sha256 TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('national','synthetic')), row_count INTEGER NOT NULL CHECK(row_count>0), status TEXT NOT NULL CHECK(status IN ('staged','active','superseded')), imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, activated_at TIMESTAMP, UNIQUE(election_id,chamber,version));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_candidacy_import ON candidacy_imports(election_id,chamber) WHERE status='active';
CREATE TABLE IF NOT EXISTS candidacy_import_rows (import_id TEXT NOT NULL REFERENCES candidacy_imports(id), constituency_code TEXT NOT NULL, candidacy_code TEXT NOT NULL, candidacy_name TEXT NOT NULL, candidacy_id INTEGER REFERENCES candidacies(id), PRIMARY KEY(import_id,constituency_code,candidacy_code));
CREATE INDEX IF NOT EXISTS candidacy_import_rows_candidacy ON candidacy_import_rows(candidacy_id);
